import { InvalidValueException, NullValueException, UndefinedValueException } from './exceptions';

/**
 * Parse a string value as a number
 *
 * @export
 * @param {(string | null | undefined)} value
 * @param {string} [propertyName]
 * @returns {number}
 * @throws {NullValueException}
 * @throws {UndefinedValueException}
 * @throws {InvalidValueException} if the string is not a valid number
 */
export function parseNumber(value: string | null | undefined, propertyName?: string): number {
    if (value === null) {
        throw new NullValueException('number', propertyName);
    }

    if (value === void 0) {
        throw new UndefinedValueException('number', propertyName);
    }

    const returnValue = parseFloat(value);

    if (isNaN(returnValue)) {
        throw new InvalidValueException('number', value, propertyName);
    }

    return returnValue;
}

/**
 * Parse a string value as an array of numbers
 *
 * @export
 * @param {(string | null | undefined)} value
 * @param {number} [digits]
 * @returns {number}
 * @throws {NullValueException}
 * @throws {UndefinedValueException}
 * @throws {InvalidValueException} if the string is not a valid set of numbers
 */
export function parseNumberArray(value: string, digits: number = 2): number[] {
    const regex = new RegExp(`.{1,${digits}}`, 'g');
    const matches = value.match(regex);

    return (matches === null) ? [] : matches.map((match) => parseFloat(match));
}
